25	struct Base58Encode
26	{
27	    static constexpr auto name = "base58Encode";
28	
29	    static void process(const ColumnString & input, ColumnString::MutablePtr & dst_column, const std::string & alphabet, size_t input_rows_count)
30	    {
31	        auto & dst_data = dst_column->getChars();
32	        auto & dst_offsets = dst_column->getOffsets();
33	
34	        /// Wikipedia states Base58 has efficiency of 73%, and we take 1.5 scale to avoid reallocation in most cases
35	        size_t current_allocated_size = ceil(1.5 * input.getChars().size());
36	
37	        dst_data.resize(current_allocated_size);
38	        dst_offsets.resize(input_rows_count);
39	
40	        const ColumnString::Offsets & src_offsets = input.getOffsets();
41	
42	        const auto * source = input.getChars().raw_data();
43	        auto * dst = dst_data.data();
44	        auto * dst_pos = dst;
45	
46	        size_t src_offset_prev = 0;
47	        size_t processed_size = 0;
48	
49	        const auto& encoder = (alphabet == "bitcoin") ? Base58::bitcoin() :
50	                             ((alphabet == "flickr") ? Base58::flickr() :
51	                             ((alphabet == "ripple") ? Base58::ripple() :
52	                                                       Base58::base58())); //GMP
53	
54	        std::string encoded;
55	        for (size_t row = 0; row < input_rows_count; ++row)
56	        {
57	            size_t srclen = src_offsets[row] - src_offset_prev - 1;
58	            /// Why we didn't use char* here?
59	            /// We don't know the size of the result string beforehand (it's not byte-to-byte encoding),
60	            /// so we may need to do many resizes (the worst case -- we'll do it for each row)
61	            /// This way we do exponential resizes and one final resize after whole operation is complete
62	            encoded.clear();
63	            if (srclen)
64	                try
65	                {
66	                    encoder.encode(encoded, source, srclen);
67	                }
68	                catch (const std::invalid_argument& e)
69	                {
70	                    throw Exception(e.what(), ErrorCodes::BAD_ARGUMENTS);
71	                }
72	                catch (const std::domain_error& e)
73	                {
74	                    throw Exception(e.what(), ErrorCodes::BAD_ARGUMENTS);
75	                }
76	            size_t outlen = encoded.size();
77	
78	            if (processed_size + outlen >= current_allocated_size)
79	            {
80	                current_allocated_size += current_allocated_size;
81	                dst_data.resize(current_allocated_size);
82	                auto processed_offset = dst_pos - dst;
83	                dst = dst_data.data();
84	                dst_pos = dst;
85	                dst_pos += processed_offset;
86	            }
87	            std::memcpy(dst_pos, encoded.c_str(), ++outlen);
88	
89	            source += srclen + 1;
90	            dst_pos += outlen;
91	
92	            dst_offsets[row] = dst_pos - dst;
93	            src_offset_prev = src_offsets[row];
94	            processed_size += outlen;
95	        }
96	
97	        dst_data.resize(dst_pos - dst);
98	    }
99	};
