177	template <typename Func>
178	class FunctionBase58Conversion : public IFunction
179	{
180	public:
181	    static constexpr auto name = Func::name;
182	
183	    static FunctionPtr create(ContextPtr)
184	    {
185	        return std::make_shared<FunctionBase58Conversion>();
186	    }
187	
188	    String getName() const override
189	    {
190	        return Func::name;
191	    }
192	
193	    bool isVariadic() const override { return true; }
194	
195	    size_t getNumberOfArguments() const override { return 0; }
196	
197	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
198	
199	    bool useDefaultImplementationForConstants() const override { return true; }
200	
201	    ColumnNumbers getArgumentsThatAreAlwaysConstant() const override { return {1}; }
202	
203	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
204	    {
205	        if (arguments.size() != 1 && arguments.size() != 2)
206	            throw Exception(
207	                "Wrong number of arguments for function " + getName() + ":  1 or 2 expected.",
208	                ErrorCodes::BAD_ARGUMENTS);
209	
210	        if (!isString(arguments[0].type))
211	            throw Exception(
212	                "Illegal type " + arguments[0].type->getName() + " of 1st argument of function " + getName() + ". Must be String.",
213	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
214	
215	        if (arguments.size() == 2 && !isString(arguments[1].type))
216	            throw Exception(
217	                "Illegal type " + arguments[1].type->getName() + " of 2nd argument of function " + getName() + ". Must be String.",
218	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
219	
220	        return std::make_shared<DataTypeString>();
221	    }
222	
223	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t input_rows_count) const override
224	    {
225	        const ColumnPtr column_string = arguments[0].column;
226	        const ColumnString * input = checkAndGetColumn<ColumnString>(column_string.get());
227	        if (!input)
228	            throw Exception(
229	                "Illegal column " + arguments[0].column->getName() + " of first argument of function " + getName() + ", must be String",
230	                ErrorCodes::ILLEGAL_COLUMN);
231	
232	        std::string alphabet = "bitcoin";
233	
234	        if (arguments.size() == 2)
235	        {
236	            const auto * alphabet_column = checkAndGetColumn<ColumnConst>(arguments[1].column.get());
237	
238	            if (!alphabet_column)
239	                throw Exception("Second argument for function " + getName() + " must be constant String", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
240	
241	            alphabet = alphabet_column->getValue<DB::String>();
242	            if (alphabet != "bitcoin" && alphabet != "ripple" && alphabet != "flickr" && alphabet != "gmp")
243	                throw Exception("Second argument for function " + getName() + " must be 'bitcoin', 'ripple', 'gmp' or 'flickr'", ErrorCodes::ILLEGAL_COLUMN);
244	
245	        }
246	
247	        auto dst_column = ColumnString::create();
248	
249	        Func::process(*input, dst_column, alphabet, input_rows_count);
250	
251	        return dst_column;
252	    }
253	};
